        ...rawUser,
        name: matched.name || rawUser.name,
        role: matched.role || rawUser.role,
        roleLabel: matched.roleLabel,
        permissions: matched.permissions || ROLE_PERMISSIONS[matched.role] || ROLE_PERMISSIONS.SALES_AGENT
