                                            setPaymentReminderModal({
                                              isOpen: true,
                                              buyer: b,
                                              unitNumber: (b.bookedUnits && b.bookedUnits[0]) || '',
                                              dueAmount: totalBal,
                                              dueDate: '15 Nov 2026',
                                              milestone: 'Milestone 2 (Foundation & Plinth)',
                                              customNotice: noticeText,
                                              copied: false
                                            });
