                                          isOpen: true,
                                          buyer: b,
                                          unitNumber: (b.bookedUnits && b.bookedUnits[0]) || '',
                                          amount: '',
                                          paymentMode: 'NEFT / RTGS',
                                          txnId: '',
                                          stage: 'Installment Milestone'
