                      const isInvoice = act.type === 'invoice';
                      const isLead = act.type === 'lead';
                      const isMedia = act.type === 'media';

                      let iconBg = '#dbeafe';
                      let iconColor = '#2563eb';
                      let IconComp = CheckCircle2;

                      if (isSold) {
                        iconBg = '#fee2e2';
                        iconColor = '#ef4444';
                        IconComp = ShieldCheck;
                      } else if (isSale) {
                        iconBg = '#dcfce7';
                        iconColor = '#16a34a';
                        IconComp = UserCheck;
                      } else if (isInvoice) {
                        iconBg = '#f3e8ff';
                        iconColor = '#7e22ce';
                        IconComp = FileText;
                      } else if (isLead) {
                        iconBg = '#fef3c7';
                        iconColor = '#d97706';
                        IconComp = Phone;
                      } else if (isMedia) {
                        iconBg = '#e0f2fe';
                        iconColor = '#0284c7';
                        IconComp = ImageIcon;
                      }

